/**
 * Rate limiting with Redis: 60s sliding window (cap = rpm + burst) and daily INCR.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { Injectable } from '@nestjs/common';
import Redis from 'ioredis';

const WINDOW_SIZE_SECONDS = 60;

export interface RateLimitPlanRow {
  readonly rpm: number;
  readonly daily: number;
  readonly burst: number;
}

export const RATE_LIMIT_PLANS: Readonly<
  Record<string, Readonly<RateLimitPlanRow>>
> = {};

/**
 * Ceiling used when the application declared no `gateway.rateLimitPlans`.
 *
 * There are no subscription tiers, so a dimension no endpoint override sets has
 * no ceiling at all. `Infinity` states that directly: every check below is
 * `count > limit`, which is never true against it. Inventing a finite default
 * here would ship a per-user limit that appears in no DSL and no config.
 */
const NO_PLAN_CEILING: Readonly<RateLimitPlanRow> = {
  rpm: Number.POSITIVE_INFINITY,
  daily: Number.POSITIVE_INFINITY,
  burst: 0,
};

const HAS_RATE_LIMIT_PLANS = Object.keys(RATE_LIMIT_PLANS).length > 0;

/**
 * @throws {Error} When the plan is missing from the baked-in map (includes ``Not found. Available: [...]``).
 */
export function planLimits(planId: string): Readonly<RateLimitPlanRow> {
  const row = RATE_LIMIT_PLANS[planId];
  if (row === undefined) {
    const available = Object.keys(RATE_LIMIT_PLANS).sort();
    const msg = `Not found. Available: [${available.join(", ")}] (unknown plan ${JSON.stringify(planId)})`;
    throw new Error(msg);
  }
  return row;
}

export interface RateLimitResult {
  allowed: boolean;
  limit: number;
  remaining: number;
  resetAtEpochSeconds: number;
}

export interface RateLimitOverride {
  rpm?: number;
  daily?: number;
  burst?: number;
}

function utcDateKey(): string {
  return new Date().toISOString().slice(0, 10);
}

@Injectable()
export class RateLimitService {
  constructor(private readonly redis: Redis) {}

  /**
   * Enforce per-plan, per-identity limits: minute window (rpm + burst) then daily.
   */
  async checkLimit(
    clientKey: string,
    planId: string,
    override?: RateLimitOverride,
  ): Promise<RateLimitResult> {
    const plan = HAS_RATE_LIMIT_PLANS ? planLimits(planId) : NO_PLAN_CEILING;
    const rpm = override?.rpm ?? plan.rpm;
    const daily = override?.daily ?? plan.daily;
    const burst = override?.burst ?? plan.burst;
    const rpmCap = rpm + burst;

    const nowSeconds = Math.floor(Date.now() / 1000);
    const wall = Date.now() / 1000;
    const windowStart = wall - WINDOW_SIZE_SECONDS;
    const minuteKey = `ns:rl:rpm:${planId}:${clientKey}`;
    const dayKey = `ns:rl:daily:${planId}:${clientKey}:${utcDateKey()}`;

    const member = `${wall.toFixed(3)}-${Math.random().toString(36).slice(2, 9)}`;
    await this.redis.zremrangebyscore(
      minuteKey,
      String(0),
      String(windowStart),
    );
    await this.redis.zadd(minuteKey, String(wall), member);
    await this.redis.expire(minuteKey, WINDOW_SIZE_SECONDS + 5);
    const rpmCount = (await this.redis.zcard(minuteKey)) as number;
    const resetAtEpochSeconds = nowSeconds + WINDOW_SIZE_SECONDS;

    if (rpmCount > rpmCap) {
      return {
        allowed: false,
        limit: rpmCap,
        remaining: 0,
        resetAtEpochSeconds,
      };
    }

    const dailyCount = (await this.redis.incr(dayKey)) as number;
    if (dailyCount === 1) {
      await this.redis.expire(dayKey, 86_400);
    }

    if (dailyCount > daily) {
      return {
        allowed: false,
        limit: daily,
        remaining: 0,
        resetAtEpochSeconds,
      };
    }

    const minuteRemaining = Math.max(0, rpmCap - rpmCount);
    const dailyRemaining = Math.max(0, daily - dailyCount);
    return {
      allowed: true,
      limit: rpmCap,
      remaining: Math.min(minuteRemaining, dailyRemaining),
      resetAtEpochSeconds,
    };
  }
}
